package build.raft.app.model

/**
 * UTS #39 section 4 confusable skeleton & dual-key matching, parity with
 * `botiverse/slock` `packages/shared/src/handleSkeleton.ts` (#17291).
 *
 * Table source: Unicode 16.0.0 `confusables.txt`
 * (SHA-256 `95bd0aad6dced5ebc63436f459c06ab21a8d107cd842fb57f5c3a1e91bca8611`, 6,355 entries),
 * mirrored verbatim from `botiverse/slock/packages/shared/src/generated/confusables.ts`.
 */
data class HandleConfusableKeys(
    /** lower(skeleton(lower(NFKC(handle)))) */
    val a: String,
    /** skeleton(NFKC(handle)) */
    val b: String,
)

private val confusablePrototypeTable: Map<Int, String> by lazy {
    val table = HashMap<Int, String>(8192)
    for (part in CONFUSABLES_TABLE_PARTS) {
        var cursor = 0
        val len = part.length
        while (cursor < len) {
            val semi = part.indexOf(';', cursor).let { if (it < 0) len else it }
            if (semi > cursor) {
                val colon = part.indexOf(':', cursor)
                if (colon in (cursor + 1) until semi) {
                    val source = part.substring(cursor, colon).toInt(16)
                    val target = decodeHexCodePoints(part, colon + 1, semi)
                    table[source] = target
                }
            }
            cursor = semi + 1
        }
    }
    table
}

private fun decodeHexCodePoints(raw: String, start: Int, end: Int): String =
    buildString {
        var i = start
        while (i < end) {
            var j = i
            while (j < end && raw[j] != ' ') j++
            if (j > i) {
                val cp = raw.substring(i, j).toInt(16)
                appendCodePoint(cp)
            }
            i = j + 1
        }
    }

private fun StringBuilder.appendCodePoint(cp: Int) {
    if (cp <= 0xFFFF) {
        append(cp.toChar())
    } else {
        val offset = cp - 0x10000
        append((0xD800 + (offset ushr 10)).toChar())
        append((0xDC00 + (offset and 0x3FF)).toChar())
    }
}

/** UTS #39 skeleton(): NFD, each code point replaced by its prototype, NFD again. */
fun confusableSkeleton(text: String): String {
    val table = confusablePrototypeTable
    val decomposed = raftNormalizeNfd(text)
    val mapped = buildString(decomposed.length) {
        var index = 0
        while (index < decomposed.length) {
            val first = decomposed[index]
            val cp: Int
            val width: Int
            if (first.isHighSurrogate() && index + 1 < decomposed.length && decomposed[index + 1].isLowSurrogate()) {
                cp = 0x10000 + ((first.code - 0xD800) shl 10) + (decomposed[index + 1].code - 0xDC00)
                width = 2
            } else {
                cp = first.code
                width = 1
            }
            val replacement = table[cp]
            if (replacement != null) {
                append(replacement)
            } else {
                append(decomposed, index, index + width)
            }
            index += width
        }
    }
    return raftNormalizeNfd(mapped)
}

/** The two keys of a handle (without a leading `@`; surrounding space ignored). */
fun handleConfusableKeys(handle: String): HandleConfusableKeys {
    val nfkc = raftNormalizeNfkc(handle.trim().removePrefix("@"))
    return HandleConfusableKeys(
        a = confusableSkeleton(nfkc.lowercase()).lowercase(),
        b = confusableSkeleton(nfkc),
    )
}

/** True when two handles may not both exist in one scope. */
fun handlesAreConfusable(first: String, second: String): Boolean {
    val x = handleConfusableKeys(first)
    val y = handleConfusableKeys(second)
    return x.a == y.a || x.b == y.b
}

